      "A": {
        "hi": "6 भागों में",
        "en": "6 Parts"
      },
      "B": {
        "hi": "8 भागों में",
        "en": "8 Parts"
      },
      "C": {
        "hi": "4 भागों में (CRE, CIE, BIE, CRIE)",
        "en": "4 Quadrants (CRE, CIE, BIE, CRIE)"
      },
